{
  "hypothesis": "Small-cap stocks showing extreme volume spikes are likely to underperform in the following days due to overreaction and subsequent mean reversion.",
  "factors": [
    {
      "name": "vol_order",
      "expression": "TS_ARGMAX($volume, 5) - TS_RANK($close, 5)",
      "explanation": "Measures the position of highest volume day within cross-sectional rank of closing prices, exploring order statistics"
    },
    {
      "name": "vol_timescale",
      "expression": "TS_ZSCORE($return, 1) - TS_ZSCORE($return, 20)",
      "explanation": "Compares short-term and long-term return volatility, exploring timescale contrast"
    },
    {
      "name": "vol_residual",
      "expression": "REGRESI($close, $volume, 5) - TS_MEDIAN(REGRESI($close, $volume, 5), 5)",
      "explanation": "Residuals from regression of price on volume, exploring residual analysis"
    },
    {
      "name": "vol_pairing",
      "expression": "TS_CORR($volume, $open, 5) / TS_CORR($volume, $close, 5)",
      "explanation": "Unusual pairing of volume with open and close prices, exploring unusual pairings"
    },
    {
      "name": "vol_shape",
      "expression": "TS_SKEW(TS_PCTCHANGE($close, 5)) - TS_SKEW(TS_PCTCHANGE($volume, 5))",
      "explanation": "Compares skewness of price and volume changes, exploring shape analysis"
    },
    {
      "name": "vol_asymmetry",
      "expression": "(FILTER($volume > TS_MEDIAN($volume, 5), $return, 5)) * TS_ZSCORE($return, 1)",
      "explanation": "Asymmetric treatment of high-volume days, exploring asymmetry in signal processing"
    }
  ]
}

